export function CardAction({
  className,
  ...props
}: ComponentPropsWithRef<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
        "col-start-2 row-span-2 row-start-1 flex min-w-0 max-w-full items-center gap-2 self-start justify-self-end",
        className,
      )}
      {...props}
