}

export function CardFooter({
  className,
  ...props
}: ComponentPropsWithRef<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn(
        "flex flex-wrap items-center gap-3 px-5 pb-5 first:pt-5 [[data-slot=card-header]+&]:pt-4",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Meter as AriaMeter,
  type MeterProps as AriaMeterProps,
  composeRenderProps,
  Label,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export interface MeterProps
  extends Omit<AriaMeterProps, "className" | "children"> {
  label?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaMeterProps["className"];
  children?: AriaMeterProps["children"];
}

export function Meter({ label, className, children, ...props }: MeterProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaMeter
      {...props}
      data-slot="meter"
      className={composeRenderProps(className, (className) =>
        cn("grid w-full gap-2", className),
      )}
    >
      {children ??
        (({ percentage, valueText }) => (
          <>
            <div className="flex items-baseline gap-3 text-sm">
              {label && (
                <Label
                  data-slot="meter-label"
                  className="min-w-0 flex-1 font-medium [overflow-wrap:anywhere]"
                >
                  {label}
                </Label>
              )}
              <span
                data-slot="meter-value"
                className="ms-auto max-w-1/2 shrink-0 text-end font-mono tabular-nums text-muted-foreground [overflow-wrap:anywhere]"
              >
                {valueText}
              </span>
            </div>
            <div
              data-slot="meter-track"
              className="h-2 overflow-hidden rounded-full bg-secondary shadow-[var(--shadow-inset)] forced-colors:border rtl:-scale-x-100"
            >
              <motion.div
                data-slot="meter-fill"
                className="h-full w-full origin-left rounded-full bg-primary forced-colors:bg-[Highlight]"
                initial={false}
                animate={{ scaleX: percentage / 100 }}
                transition={{
                  duration: reduceMotion ? 0 : duration.base,
                  ease: easeOut,
                }}
              />
            </div>
          </>
        ))}
    </AriaMeter>
  );
}

